function catalogueWebImage(product){
 if(!product)return '';
 const entry=CATALOGUE_WEB_IMAGES[String(product.source_product_id||product.id||'')];
 const n=v=>String(v||'').normalize('NFC').trim().toLocaleLowerCase('tr-TR').replace(/\s+/g,' ');
 if(!entry||n(product.name)!==n(entry.name))return '';
 if(product.brand&&entry.brand&&n(product.brand)!==n(entry.brand))return '';
 const pack=product.package_text??[product.amount,product.package].filter(Boolean).join(' • ');
 if(entry.packageText&&n(pack)!==n(entry.packageText))return '';
 return entry.image||'';
}
