/* Browser helper. The public edition is the authoritative product/news preview.
 * Optional: window.newsletterPreviewMeta={scheduleEnabled,updatedAt,title,publicUrl}.
 * No subscriber export, email dispatch or publish action is attached here.
 */
function newsletterUI(rows) {
  rows = Array.isArray(rows) ? rows : [];
  var meta = window.newsletterPreviewMeta || {};
  var publicUrl = 'https://www.okyonusedt.com/e-bulten';
  if (meta.publicUrl === 'https://www.okyonusedt.com/haftalik-bulten') publicUrl = meta.publicUrl;
  var active = rows.filter(function(x) { return x.status === 'ACTIVE'; }).length;
  var updated = meta.updatedAt ? new Date(meta.updatedAt) : null;
  var updatedLabel = updated && !isNaN(updated.getTime())
    ? new Intl.DateTimeFormat('tr-TR', {timeZone:'Europe/Istanbul',dateStyle:'long',timeStyle:'short'}).format(updated)
    : 'Yayın tarihi aşağıdaki güncel bülten önizlemesinde gösterilir.';
  var schedule = 'Haftalık içerik, yeni haftadaki ilk istekte otomatik yenilenir';
  var next = new Date(Date.now() + 3 * 60 * 60 * 1000);
  var day = next.getUTCDay();
  var delta = (8 - day) % 7;
  if (delta === 0) delta = 7;
  next.setUTCDate(next.getUTCDate() + delta);
  next.setUTCHours(0,0,0,0);
  next = new Date(next.getTime() - 3 * 60 * 60 * 1000);
  var nextLabel = new Intl.DateTimeFormat('tr-TR', {timeZone:'Europe/Istanbul',dateStyle:'long',timeStyle:'short'}).format(next);
  return '<div class="grid" style="align-items:start"><section class="moduleInfo" aria-labelledby="editionTitle">'
    + '<h3 id="editionTitle" style="margin-top:0">'+esc(meta.title || 'Haftanın E-bülteni')+'</h3>'
    + '<p>Site ziyaretçilerinin gördüğü güncel haftalık yayın ve gerçek ürün haberleri.</p>'
    + '<p><b>Son yayın:</b> '+esc(updatedLabel)+'</p>'
    + '<a href="'+publicUrl+'" target="_blank" rel="noopener" style="display:inline-block;padding:11px 14px;background:#0768b2;color:white;border-radius:9px;text-decoration:none;font-weight:bold">Sitedeki Bülteni Aç ↗</a>'
    + '</section><section class="moduleInfo"><h3 style="margin-top:0">Haftalık Güncelleme</h3><p><b>'+esc(schedule)+'</b></p>'
    + '<p>Planlanan yayın zamanı: her pazartesi <b>00.00, İstanbul saati</b>.</p>'
    + '<p>Bir sonraki planlanan zaman: '+esc(nextLabel)+'</p><p>Güncelleme, sitedeki haftalık bülten içeriğini yeniler.</p></section></div>'
    + '<section style="margin:16px 0"><h3>Yayındaki Bülten ve Ürün Haberleri</h3>'
    + '<p>Kampanyalar, katalogdaki ürünler ve haftalık duyurular aşağıdaki canlı sayfada görüntülenir.</p>'
    + '<iframe src="'+publicUrl+'" title="Yayındaki haftalık bülten ve ürün haberleri" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" style="width:100%;height:560px;border:1px solid #dce8f0;border-radius:12px;background:#fff"></iframe>'
    + '<p style="font-size:12px">Önizleme açılamazsa “Sitedeki Bülteni Aç” bağlantısını kullanın.</p></section>'
    + '<section><h3>E-bülten Aboneleri <small style="font-weight:normal">('+active+' aktif / '+rows.length+' toplam)</small></h3>'
    + '<p>Abonelik durumunu buradan yönetebilirsiniz.</p><div class="table"><table><thead><tr><th>E-posta</th><th>Ad</th><th>Onay</th><th>Durum</th><th>Tarih</th><th>İşlem</th></tr></thead><tbody>'
    + (rows.length ? rows.map(function(x) { return '<tr><td>'+esc(x.email)+'</td><td>'+esc(x.name||'—')+'</td><td>'+esc(x.consent_version||'—')+'</td><td>'+esc(x.status==='ACTIVE'?'Aktif':x.status==='UNSUBSCRIBED'?'Abonelikten ayrıldı':x.status||'—')+'</td><td>'+esc(x.updated_at||x.created_at||'—')+'</td><td>'+(x.status==='ACTIVE'?'<button type="button" data-newsletter-unsubscribe="'+esc(x.id)+'">Abonelikten Çıkar</button>':'—')+'</td></tr>'; }).join('') : '<tr><td colspan="6">Henüz e-bülten abonesi bulunmuyor.</td></tr>')
    + '</tbody></table></div></section>';
}

