        await env.DB.prepare(`INSERT INTO b2b_price_history_v1(id,product_id,old_price,new_price,actor) VALUES(?,?,?,?,?)`).bind(crypto.randomUUID(),productId,old?.price??null,price,auth.user.id).run();
